function calculateMtfSqueeze410Average(values, period, averageType) {
  const type = String(averageType || "SIMPLE").toUpperCase();
  if (type !== "HULL") return calculateMtfAdxAverage(values, period, type);
  const length = Math.max(1, Number(period) || 1);
  const halfLength = Math.max(1, Math.round(length / 2));
  const rootLength = Math.max(1, Math.round(Math.sqrt(length)));
  const half = calculateMtfAdxAverage(values, halfLength, "WEIGHTED");
  const full = calculateMtfAdxAverage(values, length, "WEIGHTED");
  const hullSource = values.map((_, index) => (
    Number.isFinite(half[index]) && Number.isFinite(full[index])
      ? 2 * half[index] - full[index]
      : null
  ));
  return calculateMtfAdxAverage(hullSource, rootLength, "WEIGHTED");
}

function aggregateDailyBarsByTradingWeek(bars) {
  const buckets = new Map();
  (Array.isArray(bars) ? bars : []).forEach((bar) => {
    const time = Number(bar?.time || 0);
    if (!Number.isFinite(time) || time <= 0) return;
    const date = new Date(time * 1000);
    const monday = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
    monday.setUTCDate(monday.getUTCDate() - ((monday.getUTCDay() + 6) % 7));
    const bucketTime = Math.floor(monday.getTime() / 1000);
    const current = buckets.get(bucketTime);
    if (!current) {
      buckets.set(bucketTime, { ...bar, time: bucketTime });
      return;
    }
    current.high = Math.max(Number(current.high || 0), Number(bar?.high || 0));
    current.low = Math.min(Number(current.low || 0), Number(bar?.low || 0));
    current.close = Number(bar?.close || current.close || 0);
    current.volume = Number(current.volume || 0) + Number(bar?.volume || 0);
  });
  return [...buckets.values()].sort((left, right) => Number(left.time) - Number(right.time));
}

function calculateMtfSqueeze410Study(
  displayBars,
  sourceBars,
  dailyBars,
  chartAggregationMinutes,
  options = {},
) {
  const display = Array.isArray(displayBars) ? displayBars : [];
  const intradaySource = Array.isArray(sourceBars) ? sourceBars : [];
  const suppliedDaily = Array.isArray(dailyBars) ? dailyBars : [];
  const chartMinutes = Math.max(1, Number(chartAggregationMinutes) || 5);
  if (!display.length) return [];
  const length = 20;
  const averageType = options.mtfSqueeze410AverageType || "SIMPLE";
  const colors = {
    none: options.mtfSqueeze410NoSqueezeColor || "#000000",
    low: options.mtfSqueeze410LowColor || "#7f6c00",
    mid: options.mtfSqueeze410MidColor || "#ffa500",
    high: options.mtfSqueeze410HighColor || "#ffffff",
  };

  return MTF_SQUEEZE_410_DEFINITIONS.map((definition) => {
    const aggregationMinutes = definition.aggregationKey
      ? Number(options[definition.aggregationKey] || 0)
      : chartMinutes;
    const aggregation = MTF_SQUEEZE_410_AGGREGATION_OPTIONS
      .find(({ value }) => value === aggregationMinutes);
    if (!Number.isFinite(aggregationMinutes) || aggregationMinutes < chartMinutes) {
      return {
        ...definition,
        aggregationMinutes,
        aggregationLabel: aggregation?.label || definition.label,
        data: [],
        latestColor: colors.none,
        latestTone: "none",
      };
    }
    const timeframeBars = aggregationMinutes === chartMinutes
      ? display
      : aggregationMinutes === 1440 && suppliedDaily.length
        ? suppliedDaily
        : aggregationMinutes === 10080 && suppliedDaily.length
          ? aggregateDailyBarsByTradingWeek(suppliedDaily)
          : aggregateChartBars(intradaySource, aggregationMinutes);
    const closes = timeframeBars.map((bar) => Number(bar?.close || 0));
    const trueRanges = calculateTrueRanges(timeframeBars);
    const keltnerAverage = calculateMtfSqueeze410Average(closes, length, averageType);
    const averageTrueRange = calculateMtfSqueeze410Average(trueRanges, length, averageType);
    const bollingerAverage = calculateRollingAverage(closes, length);
    const bollingerDeviation = calculateRollingStdDev(closes, length);
    const classified = timeframeBars.flatMap((bar, index) => {
      if (index < length - 1
        || !Number.isFinite(keltnerAverage[index])
        || !Number.isFinite(averageTrueRange[index])
        || !Number.isFinite(bollingerAverage[index])
        || !Number.isFinite(bollingerDeviation[index])) return [];
      const bollingerUpper = bollingerAverage[index] + 2 * bollingerDeviation[index];
      const keltnerBase = keltnerAverage[index];
      const atr = averageTrueRange[index];
      const highDelta = bollingerUpper - (keltnerBase + atr);
      const midDelta = bollingerUpper - (keltnerBase + 1.5 * atr);
      const lowDelta = bollingerUpper - (keltnerBase + 2 * atr);
      const tone = highDelta <= 0 ? "high" : midDelta <= 0 ? "mid" : lowDelta <= 0 ? "low" : "none";
      return [{
        time: Number(bar.time),
        color: colors[tone],
        tone,
      }];
    });
    let classifiedIndex = -1;
    const data = display.flatMap((bar) => {
      const time = Number(bar?.time || 0);
      while (classifiedIndex + 1 < classified.length
        && Number(classified[classifiedIndex + 1].time) <= time) {
        classifiedIndex += 1;
      }
      if (classifiedIndex < 0) return [];
      return [{
        time,
        value: definition.level + 0.18,
        color: classified[classifiedIndex].color,
      }];
    });
    const latestState = classified[classifiedIndex] || classified.at(-1);
    return {
      ...definition,
      aggregationMinutes,
      aggregationLabel: definition.aggregationKey
        ? (aggregation?.label || definition.label)
        : `${chartMinutes}m`,
      data,
      latestColor: latestState?.color || colors.none,
      latestTone: latestState?.tone || "none",
    };
  });
}

function calculateMtfAdxLines(bars, options = {}) {
  const source = Array.isArray(bars) ? bars : [];
  const length = Math.max(1, Math.min(100, Number(options.mtfAdxLength) || 10));
  if (source.length < 2) {
    return {
      plus: [],
      minus: [],
      adx: [],
      signals: {
        call: [], put: [], strongCall: [], strongPut: [], strongCall2: [], strongPut2: [],
      },
    };
  }
  const trueRanges = [];
  const plusDm = [];
  const minusDm = [];
  source.forEach((bar, index) => {
    const high = Number(bar?.high);
    const low = Number(bar?.low);
    const previous = source[index - 1];
    const previousClose = Number(previous?.close);
    const highDifference = index ? high - Number(previous?.high) : 0;
    const lowDifference = index ? Number(previous?.low) - low : 0;
    trueRanges.push(index
      ? Math.max(high - low, Math.abs(high - previousClose), Math.abs(low - previousClose))
      : high - low);
    plusDm.push(highDifference > lowDifference && highDifference > 0 ? highDifference : 0);
    minusDm.push(lowDifference > highDifference && lowDifference > 0 ? lowDifference : 0);
  });
  const averageType = options.mtfAdxAverageType || "WILDERS";
  const atr = calculateMtfAdxAverage(trueRanges, length, averageType);
  const smoothPlus = calculateMtfAdxAverage(plusDm, length, averageType);
  const smoothMinus = calculateMtfAdxAverage(minusDm, length, averageType);
  const plus = source.map((bar, index) => (
    Number.isFinite(atr[index]) && atr[index] > 0
      ? 100 * Number(smoothPlus[index] || 0) / atr[index]
      : null
  ));
  const minus = source.map((bar, index) => (
    Number.isFinite(atr[index]) && atr[index] > 0
      ? 100 * Number(smoothMinus[index] || 0) / atr[index]
      : null
  ));
  const dx = source.map((bar, index) => {
    if (!Number.isFinite(plus[index]) || !Number.isFinite(minus[index])) return null;
    const total = plus[index] + minus[index];
    return total > 0 ? 100 * Math.abs(plus[index] - minus[index]) / total : 0;
  });
  const adx = calculateMtfAdxAverage(dx, length, averageType);
  const lineData = (values) => source.flatMap((bar, index) => (
    Number.isFinite(values[index])
      ? [{ time: Number(bar.time), value: Number(values[index].toFixed(4)) }]
      : []
  ));
  const signals = {
    call: [],
    put: [],
    strongCall: [],
    strongPut: [],
    strongCall2: [],
    strongPut2: [],
  };
  source.forEach((bar, index) => {
    if (!index || !Number.isFinite(adx[index])) return;
    const plusCrossedMinus = Number(plus[index - 1]) <= Number(minus[index - 1])
      && Number(plus[index]) > Number(minus[index]);
    const minusCrossedPlus = Number(minus[index - 1]) <= Number(plus[index - 1])
      && Number(minus[index]) > Number(plus[index]);
    const plusCrossedStrong = Number(plus[index - 1]) <= 25 && Number(plus[index]) > 25;
    const minusCrossedStrong = Number(minus[index - 1]) <= 25 && Number(minus[index]) > 25;
    const time = Number(bar.time);
    if (plusCrossedMinus) signals.call.push({ time, value: 20 });
    if (minusCrossedPlus) signals.put.push({ time, value: 20 });
    if (plusCrossedStrong) {
      signals.strongCall.push({ time, value: 25 });
      signals.strongCall2.push({ time, value: Number(adx[index].toFixed(4)) });
    }
    if (minusCrossedStrong) {
      signals.strongPut.push({ time, value: 25 });
      signals.strongPut2.push({ time, value: Number(adx[index].toFixed(4)) });
    }
  });
  return {
    plus: lineData(plus),
    minus: lineData(minus),
    adx: lineData(adx),
    signals,
  };
}

function chartColorWithAlpha(color, alpha) {
  const value = String(color || "").trim();
  const match = /^#([0-9a-f]{6})$/i.exec(value);
  if (!match) return value;
  const numeric = Number.parseInt(match[1], 16);
  return `rgba(${(numeric >> 16) & 255},${(numeric >> 8) & 255},${numeric & 255},${alpha})`;
}

const MTF_MA_LEVEL_DEFINITIONS = Object.freeze([
  { key: "ema1", average: "EMA", periodOption: "mtfMaMovAvg1", fallbackPeriod: 9, colorOption: "mtfMaVioletColor" },
  { key: "ema2", average: "EMA", periodOption: "mtfMaMovAvg2", fallbackPeriod: 21, colorOption: "mtfMaGoldColor" },
  { key: "ema3", average: "EMA", periodOption: "mtfMaMovAvg3", fallbackPeriod: 50, colorOption: "mtfMaAquaColor" },
  { key: "sma4", average: "SMA", periodOption: "mtfMaMovAvg4", fallbackPeriod: 200, colorOption: "mtfMaGreenColor" },
  { key: "sma3", average: "SMA", periodOption: "mtfMaMovAvg3", fallbackPeriod: 50, colorOption: "mtfMaBlueColor" },
  { key: "ema4", average: "EMA", periodOption: "mtfMaMovAvg4", fallbackPeriod: 200, colorOption: "mtfMaMintColor" },
]);

const MTF_MA_LEVEL_TIMEFRAMES = Object.freeze([
  { key: "DAY", option: "mtfMaShowDaily", suffix: "D", lineWidth: 1 },
  { key: "WEEK", option: "mtfMaShowWeekly", suffix: "Wk", lineWidth: 3 },
  // Lightweight Charts supports line weights through 4; this is its closest
  // match to the ThinkScript monthly SetLineWeight(5).
  { key: "MONTH", option: "mtfMaShowMonthly", suffix: "Mo", lineWidth: 4 },
]);

// Smallest series an average may be computed from. calculateNumericEma seeds
// itself with source[0], so a short series returns roughly that seed no matter
// how long the requested period is - a 200-period EMA of three closes is just
// the last close wearing a 200 label. Long periods still plot once the series
// is at least this deep (a decade of dailies is ~120 monthly closes, so 200eMo
// keeps rendering); stub tapes plot nothing.
const MTF_MA_MIN_AVERAGE_SAMPLES = 30;

function buildMtfMaLevelsStudy(chartBars, dailyBars, easternDateFormatter, options = {}) {
  // Family toggles gate the whole ribbon, so switching EMA off clears its four
  // lines - and their name bubbles - across daily, weekly and monthly at once.
  // Profiles saved before these keys existed have neither, and `!== false`
  // keeps both families drawn for them without needing a migration.
  const visibleDefinitions = MTF_MA_LEVEL_DEFINITIONS.filter((definition) => (
    definition.average === "EMA" ? options.mtfMaShowEma !== false : options.mtfMaShowSma !== false
  ));
  if (!visibleDefinitions.length) return [];
  const intraday = Array.isArray(chartBars) ? chartBars : [];
  const suppliedDaily = Array.isArray(dailyBars) ? dailyBars : [];
  const latestChartBar = intraday.at(-1);
  const latestClose = Number(latestChartBar?.close || 0);
  if (!latestChartBar || !Number.isFinite(latestClose) || latestClose <= 0) return [];
  // These averages need the symbol's OWN daily history. On a ticker switch the
  // intraday seed tape arrives first; synthesizing a "live day" bar from it left
  // exactly one daily close, and an EMA of one close equals that close for every
  // period - so all twelve labels stacked on the price line for a second or two
  // until the real history landed. Draw nothing rather than draw them wrong.
  if (suppliedDaily.length < MTF_MA_MIN_AVERAGE_SAMPLES) return [];

  const dateKeyFor = (bar) => {
    if (typeof bar?.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(bar.date)) return bar.date;
    return easternDateKey(easternDateFormatter, bar?.time);
  };
  const dailyByDate = new Map();
  suppliedDaily.forEach((bar) => {
    const date = dateKeyFor(bar);
    const close = Number(bar?.close || 0);
    if (!date || !Number.isFinite(close) || close <= 0) return;
    dailyByDate.set(date, { ...bar, date, close });
  });

  // Keep the current higher-timeframe candle live, matching close(period =
  // DAY/WEEK/MONTH) in ThinkScript instead of waiting for the daily snapshot.
  const latestDate = dateKeyFor(latestChartBar);
  const liveDayBars = intraday.filter((bar) => dateKeyFor(bar) === latestDate);
  if (latestDate && liveDayBars.length) {
    const existing = dailyByDate.get(latestDate);
    dailyByDate.set(latestDate, {
      ...(existing || {}),
      date: latestDate,
      time: Number(existing?.time || liveDayBars[0]?.time || latestChartBar.time),
      open: Number(existing?.open || liveDayBars[0]?.open || latestChartBar.open),
      high: Math.max(Number(existing?.high || -Infinity), ...liveDayBars.map((bar) => Number(bar?.high || -Infinity))),
      low: Math.min(Number(existing?.low || Infinity), ...liveDayBars.map((bar) => Number(bar?.low || Infinity))),
      close: latestClose,
      volume: liveDayBars.reduce((sum, bar) => sum + Number(bar?.volume || 0), 0),
    });
  }

  const normalizedDaily = [...dailyByDate.values()]
    .sort((left, right) => String(left.date).localeCompare(String(right.date)));
  if (!normalizedDaily.length) return [];

  const weekKey = (date) => {
    const [year, month, day] = String(date).split("-").map(Number);
    const value = new Date(Date.UTC(year, month - 1, day));
    const daysSinceMonday = (value.getUTCDay() + 6) % 7;
    value.setUTCDate(value.getUTCDate() - daysSinceMonday);
    return value.toISOString().slice(0, 10);
  };
  const closesFor = (timeframe) => {
    if (timeframe === "DAY") return normalizedDaily.map((bar) => Number(bar.close));
    const grouped = new Map();
    normalizedDaily.forEach((bar) => {
      const period = timeframe === "WEEK" ? weekKey(bar.date) : String(bar.date).slice(0, 7);
      grouped.set(period, Number(bar.close));
    });
    return [...grouped.values()];
  };
  const proximity = Math.max(0, Math.min(100, Number(options.mtfMaProximity) || 0));
  const averageValue = (values, average, period) => {
    if (!values.length || (average === "SMA" && values.length < period)) return null;
    if (average === "EMA") {
      if (values.length < Math.min(period, MTF_MA_MIN_AVERAGE_SAMPLES)) return null;
      return calculateNumericEma(values, period).at(-1);
    }
    return values.slice(-period).reduce((sum, value) => sum + Number(value || 0), 0) / period;
  };

  return MTF_MA_LEVEL_TIMEFRAMES.flatMap((timeframe) => {
    if (options[timeframe.option] === false) return [];
    const closes = closesFor(timeframe.key);
    return visibleDefinitions.flatMap((definition) => {
      const period = Math.max(1, Math.min(500, Number(options[definition.periodOption]) || definition.fallbackPeriod));
      const value = averageValue(closes, definition.average, period);
      if (!Number.isFinite(Number(value)) || Number(value) <= 0) return [];
      const lower = Number(value) * (1 - proximity / 100);
      const upper = Number(value) * (1 + proximity / 100);
      if (latestClose < lower || latestClose > upper) return [];
      return [{
        key: `${timeframe.key}-${definition.key}`,
        value: Number(Number(value).toFixed(4)),
        color: options[definition.colorOption],
        lineWidth: timeframe.lineWidth,
        label: `${period}${definition.average === "EMA" ? "e" : "s"}${timeframe.suffix}`,
      }];
    });
  });
}


function chartHhmmToMinutes(value, fallback) {
  const numeric = Number(value);
  const raw = String(Math.max(0, Number.isFinite(numeric) ? numeric : fallback)).padStart(4, "0").slice(-4);
  return Math.min(23, Number(raw.slice(0, 2)) || 0) * 60 + Math.min(59, Number(raw.slice(2, 4)) || 0);
}

function chartMtfCloudSessionCutoff(source, easternSessionFormatter, {
  limitRecentSessions,
  sessionsBack,
  rthStartTime,
  rthEndTime,
  defaultSessionsBack,
}) {
  const rthStart = chartHhmmToMinutes(rthStartTime, 500);
  const rthEnd = chartHhmmToMinutes(rthEndTime, 1600);
  const sessionStarts = [];
  const seenRthDates = new Set();
  source.forEach((bar) => {
    const time = Number(bar?.time || 0);
    if (!time) return;
    const { dateKey: date, minutes: minute } = easternSessionParts(easternSessionFormatter, time);
    if (minute >= rthStart && minute < rthEnd && !seenRthDates.has(date)) {
      seenRthDates.add(date);
      sessionStarts.push(time);
    }
  });
  if (limitRecentSessions === false || !sessionStarts.length) return Number.NEGATIVE_INFINITY;
  const count = Math.max(1, Math.min(30, Number(sessionsBack) || defaultSessionsBack));
  return sessionStarts[Math.max(0, sessionStarts.length - count)];
}

const AUTO_FIB_TIMEFRAMES = Object.freeze([
  { key: "5m", label: "5m", minutes: 5, optionKey: "autoFib5m" },
  { key: "10m", label: "10m", minutes: 10, optionKey: "autoFib10m" },
  { key: "15m", label: "15m", minutes: 15, optionKey: "autoFib15m" },
  { key: "30m", label: "30m", minutes: 30, optionKey: "autoFib30m" },
  { key: "1h", label: "1h", minutes: 60, optionKey: "autoFib1h" },
  { key: "2h", label: "2h", minutes: 120, optionKey: "autoFib2h" },
  { key: "4h", label: "4h", minutes: 240, optionKey: "autoFib4h" },
  { key: "day", label: "Daily", minutes: 1440, optionKey: "autoFibDay" },
]);
// v3 (2026-09-30): lookback 20 = his TOS study inputs (Day, lookback 20).
// Checked on TEAM: 20-day high 200.00 / low 168.05 -> 50% = 184.025, the
// 184.03 line on his TOS chart. 40 put the line somewhere else.
const AUTO_FIB_STUDY_VERSION = "tos-20-day-daily-live-v3";

function migrateAutoFibChartOptions(saved = {}) {
  if (saved.autoFibStudyVersion === AUTO_FIB_STUDY_VERSION) return {};
  return {
    autoFibStudyVersion: AUTO_FIB_STUDY_VERSION,
    autoFibLookbackPeriod: 20,
    autoFib5m: false,
    autoFib10m: false,
    autoFib15m: false,
    autoFib30m: false,
    autoFib1h: false,
    autoFib2h: false,
    autoFib4h: false,
    autoFibDay: true,
  };
}

// Translation of shared_AutoFib_SingleTF_v20263. Each checked timeframe is
// treated as one independent SingleTF instance, which keeps the TOS study's
// calculation intact without introducing a timeframe dropdown.
function calculateAutoFibSingleTfStudies(
  sourceBars,
  suppliedDailyBars,
  displayedBars,
  displayedMinutes,
  easternSessionFormatter,
  options = {},
) {
  const intradaySource = Array.isArray(sourceBars) ? sourceBars : [];
  if (!intradaySource.length || !easternSessionFormatter?.formatToParts) return [];
  const chartMinutes = Math.max(1, Number(displayedMinutes) || 1);
  const chartSource = (Array.isArray(displayedBars) ? displayedBars : [])
    .map((bar) => ({ ...bar, time: Number(bar?.time || 0) }))
    .filter((bar) => Number.isFinite(bar.time) && bar.time > 0)
    .sort((left, right) => left.time - right.time);
  const lookback = Math.max(1, Math.min(500, Number(options.autoFibLookbackPeriod) || 20));
  const sessionsBack = Math.max(1, Math.min(30, Number(options.autoFibSessionsBack) || 1));
  const limitRecentSessions = options.autoFibLimitRecentSessions !== false;
  const dateKeyForTime = (time) => easternSessionParts(easternSessionFormatter, time).dateKey;
  const suppliedDailyByDate = new Map();
  (Array.isArray(suppliedDailyBars) ? suppliedDailyBars : []).forEach((bar) => {
    const time = Number(bar?.time || 0);
    const date = String(bar?.date || "") || (time > 0 ? dateKeyForTime(time) : "");
    if (!date || !Number.isFinite(time) || time <= 0) return;
    suppliedDailyByDate.set(date, {
      ...bar,
      date,
      time,
      open: Number(bar?.open),
      high: Number(bar?.high),
      low: Number(bar?.low),
      close: Number(bar?.close),
      volume: Number(bar?.volume || 0),
    });
  });
  // Schwab's cached daily history can lag the streaming quote during the
  // current session. Merge today's one-minute/5-minute bars into the Daily
  // candle so a 40-DAY AutoFib matches the live TOS value (NOW ≈ 116.18).
  const latestIntradayDate = intradaySource.length
    ? dateKeyForTime(intradaySource.at(-1).time)
    : "";
  const liveDailyBars = latestIntradayDate
    ? intradaySource.filter((bar) => dateKeyForTime(bar.time) === latestIntradayDate)
    : [];
  if (liveDailyBars.length) {
    const existing = suppliedDailyByDate.get(latestIntradayDate);
    const first = liveDailyBars[0];
    const latest = liveDailyBars.at(-1);
    const liveHigh = Math.max(...liveDailyBars.map((bar) => Number(bar?.high)));
    const liveLow = Math.min(...liveDailyBars.map((bar) => Number(bar?.low)));
    suppliedDailyByDate.set(latestIntradayDate, {
      ...(existing || {}),
      date: latestIntradayDate,
      time: Number(existing?.time || first.time),
      open: Number(existing?.open || first.open),
      high: Math.max(Number(existing?.high || Number.NEGATIVE_INFINITY), liveHigh),
      low: Math.min(Number(existing?.low || Number.POSITIVE_INFINITY), liveLow),
      close: Number(latest?.close),
      volume: Math.max(
        Number(existing?.volume || 0),
        liveDailyBars.reduce((sum, bar) => sum + Number(bar?.volume || 0), 0),
      ),
    });
  }
  const liveDailySource = [...suppliedDailyByDate.values()]
    .filter((bar) => (
      Number.isFinite(bar.time)
      && Number.isFinite(bar.high)
      && Number.isFinite(bar.low)
      && Number.isFinite(bar.close)
    ))
    .sort((left, right) => left.time - right.time);
  const intradayCutoff = chartMtfCloudSessionCutoff(intradaySource, easternSessionFormatter, {
    limitRecentSessions,
    sessionsBack,
    rthStartTime: options.autoFibRthStartTime,
    rthEndTime: options.autoFibRthEndTime,
    defaultSessionsBack: 1,
  });

  return AUTO_FIB_TIMEFRAMES.flatMap((definition) => {
    // Match TOS secondary-aggregation rules: a checked source timeframe below
    // the chart's own timeframe is unavailable and is therefore skipped.
    if (options[definition.optionKey] !== true || definition.minutes < chartMinutes) return [];
    const timeframeBars = (definition.minutes === 1440 && liveDailySource.length
      ? liveDailySource
      : aggregateChartBars(intradaySource, definition.minutes))
      .map((bar) => ({
        ...bar,
        time: Number(bar?.time || 0),
        high: Number(bar?.high),
        low: Number(bar?.low),
        close: Number(bar?.close),
      }))
      .filter((bar) => (
        Number.isFinite(bar.time)
        && bar.time > 0
        && Number.isFinite(bar.high)
        && Number.isFinite(bar.low)
        && Number.isFinite(bar.close)
      ))
      .sort((left, right) => left.time - right.time);
    if (timeframeBars.length < lookback) return [];

    const cutoffTime = definition.minutes >= 1440 && limitRecentSessions
      ? Number(timeframeBars[Math.max(0, timeframeBars.length - sessionsBack)]?.time || 0)
      : intradayCutoff;
    const calculationPoints = [];
    for (let index = lookback - 1; index < timeframeBars.length; index += 1) {
      const bar = timeframeBars[index];
      const endTime = Number(bar.time) + definition.minutes * 60;
      const window = timeframeBars.slice(index - lookback + 1, index + 1);
      const highestHigh = Math.max(...window.map((item) => Number(item.high)));
      const lowestLow = Math.min(...window.map((item) => Number(item.low)));
      if (!Number.isFinite(highestHigh) || !Number.isFinite(lowestLow)) continue;
      const range = highestHigh - lowestLow;
      const fib50 = lowestLow + range * 0.5;
      const above50 = Number(bar.close) > fib50;
      const fibGold = lowestLow + range * (above50 ? 0.618 : 0.382);
      calculationPoints.push({
        time: Number(bar.time),
        endTime,
        date: String(bar?.date || "") || dateKeyForTime(bar.time),
        highestHigh,
        lowestLow,
        fib50,
        fibGold,
        above50,
        closeAboveGold: Number(bar.close) > fibGold,
      });
    }
    const calculationByTime = new Map(
      calculationPoints.map((point) => [Number(point.time), point]),
    );
    const calculationByDate = new Map(
      calculationPoints.map((point) => [point.date, point]),
    );
    const points = chartSource.length
      ? chartSource.flatMap((bar) => {
        if (Number(bar.time) < cutoffTime) return [];
        const sourcePoint = definition.minutes >= 1440
          ? calculationByDate.get(dateKeyForTime(bar.time))
          : calculationByTime.get(
            Math.floor(Number(bar.time) / (definition.minutes * 60)) * definition.minutes * 60,
          );
        if (!sourcePoint) return [];
        // TOS colors the higher-aggregation Fib plot from each displayed
        // candle's close. Do not repeat the latest Daily close across the
        // entire intraday session or the earlier dark-red "below Fib" segment
        // disappears after price crosses the level.
        const displayedClose = Number(bar?.close);
        const displayedAbove50 = Number.isFinite(displayedClose)
          ? displayedClose > sourcePoint.fib50
          : sourcePoint.above50;
        const displayedFibGold = sourcePoint.lowestLow
          + (sourcePoint.highestHigh - sourcePoint.lowestLow)
            * (displayedAbove50 ? 0.618 : 0.382);
        return [{
          ...sourcePoint,
          time: Number(bar.time),
          endTime: Number(bar.time) + chartMinutes * 60,
          above50: displayedAbove50,
          fibGold: displayedFibGold,
          closeAboveGold: Number.isFinite(displayedClose)
            ? displayedClose > displayedFibGold
            : sourcePoint.closeAboveGold,
        }];
      })
      : calculationPoints.filter((point) => Number(point.endTime) > cutoffTime);
    if (!points.length) return [];

    if (options.autoFibExtendIntoExpansion === true) {
      const latest = points.at(-1);
      points.push({
        ...latest,
        time: Number(latest.time) + chartMinutes * 60,
        endTime: Number(latest.endTime) + chartMinutes * 60,
      });
    }
    const linePoint = (point, value, color) => ({
      time: point.time,
      value: Number(Number(value).toFixed(4)),
      color,
    });
    const fib50 = points.map((point) => linePoint(
      point,
      point.fib50,
      point.above50 ? options.autoFibAbove50Color : options.autoFibBelow50Color,
    ));
    const fibGold = points.map((point) => linePoint(
      point,
      point.fibGold,
      point.closeAboveGold ? options.autoFibAboveGoldColor : options.autoFibBelowGoldColor,
    ));
    return [{
      ...definition,
      lines: {
        fib50: options.autoFibShowFib50 !== false ? fib50 : [],
        fibGold: options.autoFibShowFibGold !== false ? fibGold : [],
        high: options.autoFibShowHighLow === true
          ? points.map((point) => linePoint(point, point.highestHigh, options.autoFibHighColor))
          : [],
        low: options.autoFibShowHighLow === true
          ? points.map((point) => linePoint(point, point.lowestLow, options.autoFibLowColor))
          : [],
      },
      cloud: options.autoFibShowCloud !== false ? { fib50, fibGold } : { fib50: [], fibGold: [] },
    }];
  });
}

const ICHIMOKU_TIMEFRAMES = Object.freeze([
  { key: "5m", label: "5m", minutes: 5, optionKey: "ichimoku5m" },
  { key: "10m", label: "10m", minutes: 10, optionKey: "ichimoku10m" },
  { key: "15m", label: "15m", minutes: 15, optionKey: "ichimoku15m" },
  { key: "30m", label: "30m", minutes: 30, optionKey: "ichimoku30m" },
  { key: "1h", label: "1h", minutes: 60, optionKey: "ichimoku1h" },
  { key: "2h", label: "2h", minutes: 120, optionKey: "ichimoku2h" },
  { key: "4h", label: "4h", minutes: 240, optionKey: "ichimoku4h" },
  { key: "day", label: "Daily", minutes: 1440, optionKey: "ichimokuDay" },
]);

function calculateIchimokuStudy(
  sourceBars,
  suppliedDailyBars,
  displayedBars,
  displayedMinutes,
  easternSessionFormatter,
  timeframeMinutes,
  options = {},
) {
  const emptyStudy = {
    lines: { tenkan: [], kijun: [], spanA: [], spanB: [], chikou: [] },
    cloud: { tenkan: [], kijun: [], spanA: [], spanB: [] },
    signals: [],
    label: null,
  };
  const timeframe = ICHIMOKU_TIMEFRAMES.some(({ minutes }) => minutes === Number(timeframeMinutes))
    ? Number(timeframeMinutes)
    : 5;
  // ThinkScript does not permit a secondary aggregation below the chart's
  // aggregation. Mirror that behavior instead of synthesizing lower-TF data.
  if (timeframe < Math.max(1, Number(displayedMinutes) || 1)) return emptyStudy;

  const source = (timeframe === 1440 && Array.isArray(suppliedDailyBars) && suppliedDailyBars.length
    ? suppliedDailyBars
    : aggregateChartBars(sourceBars, timeframe))
    .map((bar) => ({
      ...bar,
      time: Number(bar?.time || 0),
      high: Number(bar?.high),
      low: Number(bar?.low),
      close: Number(bar?.close),
    }))
    .filter((bar) => (
      Number.isFinite(bar.time)
      && bar.time > 0
      && Number.isFinite(bar.high)
      && Number.isFinite(bar.low)
      && Number.isFinite(bar.close)
    ))
    .sort((left, right) => left.time - right.time);
  if (!source.length || !easternSessionFormatter?.formatToParts) return emptyStudy;

  const tenkanPeriod = Math.max(1, Math.min(500, Number(options.ichimokuTenkanPeriod) || 9));
  const kijunPeriod = Math.max(1, Math.min(500, Number(options.ichimokuKijunPeriod) || 26));
  const midpointAt = (endIndex, length) => {
    const startIndex = endIndex - length + 1;
    if (startIndex < 0) return null;
    let highest = Number.NEGATIVE_INFINITY;
    let lowest = Number.POSITIVE_INFINITY;
    for (let index = startIndex; index <= endIndex; index += 1) {
      highest = Math.max(highest, source[index].high);
      lowest = Math.min(lowest, source[index].low);
    }
    return Number.isFinite(highest) && Number.isFinite(lowest) ? (highest + lowest) / 2 : null;
  };
  const rounded = (value) => Number(Number(value).toFixed(4));
  const tenkanValues = source.map((_, index) => midpointAt(index, tenkanPeriod));
  const kijunValues = source.map((_, index) => midpointAt(index, kijunPeriod));
  const spanAValues = source.map((_, index) => {
    const displacedIndex = index - kijunPeriod;
    const tenkan = tenkanValues[displacedIndex];
    const kijun = kijunValues[displacedIndex];
    return Number.isFinite(tenkan) && Number.isFinite(kijun) ? (tenkan + kijun) / 2 : null;
  });
  const spanBValues = source.map((_, index) => midpointAt(index - kijunPeriod, 2 * kijunPeriod));
  const firstDisplayedTime = Number((Array.isArray(displayedBars) ? displayedBars : []).at(0)?.time || 0);
  const visibleFloor = firstDisplayedTime > 0 ? firstDisplayedTime - timeframe * 60 : Number.NEGATIVE_INFINITY;
  const linePoint = (bar, value, extras = {}) => (
    Number.isFinite(value) && bar.time >= visibleFloor
      ? { time: bar.time, value: rounded(value), ...extras }
      : null
  );
  const lines = {
    tenkan: source.map((bar, index) => linePoint(bar, tenkanValues[index])).filter(Boolean),
    kijun: source.map((bar, index) => linePoint(bar, kijunValues[index])).filter(Boolean),
    spanA: source.map((bar, index) => linePoint(bar, spanAValues[index])).filter(Boolean),
    spanB: source.map((bar, index) => linePoint(bar, spanBValues[index], {
      color: bar.close < spanBValues[index]
        ? options.ichimokuSpanBBearColor
        : options.ichimokuSpanBBullColor,
    })).filter(Boolean),
    // close[-kijun] places today's close on the bar kijun periods ago.
    chikou: source.flatMap((bar, index) => {
      const targetIndex = index - kijunPeriod;
      if (targetIndex < 0) return [];
      const target = source[targetIndex];
      const point = linePoint(target, bar.close);
      return point ? [point] : [];
    }),
  };

  // TOS draws a secondary aggregation as a step across the chart's own bars and
  // never gives it a bar column of its own. Daily buckets sit at 00:00 ET while
  // the 4H grid is anchored to 01:00 ET, so plotting a Daily study at its own
  // timestamps inserted a phantom column that rendered as a missing candle.
  // Chikou is drawn kijun periods back and must not be held to the right edge.
  const onChartGrid = timeframe === Math.max(1, Number(displayedMinutes) || 1);
  const gridLines = onChartGrid ? lines : {
    tenkan: holdStudyPointsOnChartGrid(lines.tenkan, displayedBars),
    kijun: holdStudyPointsOnChartGrid(lines.kijun, displayedBars),
    spanA: holdStudyPointsOnChartGrid(lines.spanA, displayedBars),
    spanB: holdStudyPointsOnChartGrid(lines.spanB, displayedBars),
    chikou: holdStudyPointsOnChartGrid(lines.chikou, displayedBars, {
      extendPastLastPoint: false,
    }),
  };

  const cutoffTime = chartMtfCloudSessionCutoff(source, easternSessionFormatter, {
    limitRecentSessions: options.ichimokuLimitRecentSessions !== false,
    sessionsBack: options.ichimokuSessionsBack,
    rthStartTime: options.ichimokuRthStartTime,
    rthEndTime: options.ichimokuRthEndTime,
    defaultSessionsBack: 1,
  });
  const recent = (points) => points.filter((point) => Number(point.time) >= cutoffTime);
  const signals = [];
  for (let index = 1; index < source.length; index += 1) {
    const previousTenkan = tenkanValues[index - 1];
    const previousKijun = kijunValues[index - 1];
    const tenkan = tenkanValues[index];
    const kijun = kijunValues[index];
    if (![previousTenkan, previousKijun, tenkan, kijun].every(Number.isFinite)) continue;
    const bullishCross = previousTenkan <= previousKijun && tenkan > kijun;
    const bearishCross = previousTenkan >= previousKijun && tenkan < kijun;
    if ((!bullishCross && !bearishCross) || source[index].time < cutoffTime) continue;
    const spanB = spanBValues[index];
    signals.push({
      key: `ichimoku-${bullishCross ? "bull" : "bear"}-${source[index].time}`,
      time: source[index].time,
      tone: bullishCross ? "bull" : "bear",
      position: bullishCross ? "belowBar" : "aboveBar",
      shape: bullishCross ? "arrowUp" : "arrowDown",
      showBubble: options.ichimokuBubbles === true
        && (bullishCross ? source[index].close > spanB : source[index].close < spanB),
    });
  }
  const latestIndex = source.length - 1;
  const latestSpanB = spanBValues[latestIndex];
  const latestClose = source[latestIndex].close;
  const labelTone = latestClose > latestSpanB ? "bull" : latestClose < latestSpanB ? "bear" : "";
  const label = options.ichimokuShowLabel === true
    && source[latestIndex].time >= cutoffTime
    && Number.isFinite(latestSpanB)
    && labelTone
    ? {
      text: "Ichi",
      tone: labelTone,
    }
    : null;
  return {
    lines: gridLines,
    cloud: {
      tenkan: recent(gridLines.tenkan),
      kijun: recent(gridLines.kijun),
      spanA: recent(gridLines.spanA),
      spanB: recent(gridLines.spanB),
    },
    // A cross is a discrete event: snap it onto the containing chart bar rather
    // than holding it, so no signal is invented on a later bar.
    signals: onChartGrid ? signals : snapStudyPointsToChartGrid(signals, displayedBars),
    label,
  };
}

function migrateIchimokuChartOptions(saved = {}) {
  const hasTimeframeCheckboxes = ICHIMOKU_TIMEFRAMES.some(({ optionKey }) => (
    Object.prototype.hasOwnProperty.call(saved, optionKey)
  ));
  const legacyTimeframe = ICHIMOKU_TIMEFRAMES.some(({ minutes }) => minutes === Number(saved.ichimokuTimeframe))
    ? Number(saved.ichimokuTimeframe)
    : 5;
  const legacySpansVisible = saved.ichimokuShowIchimoku !== false;
  return {
    ...(!hasTimeframeCheckboxes
      ? Object.fromEntries(ICHIMOKU_TIMEFRAMES.map(({ minutes, optionKey }) => [
        optionKey,
        minutes === legacyTimeframe,
      ]))
      : {}),
    ...(!Object.prototype.hasOwnProperty.call(saved, "ichimokuShowSpanA")
      ? { ichimokuShowSpanA: legacySpansVisible }
      : {}),
    ...(!Object.prototype.hasOwnProperty.call(saved, "ichimokuShowSpanB")
      ? { ichimokuShowSpanB: legacySpansVisible }
      : {}),
    ichimokuStudyVersion: "multi-timeframe-span-controls-v2",
  };
}

const TOS_MTF_SIGNAL_LABEL_STUDY_VERSION = "tos-thinkscript-signal-bubbles-v4";

function migrateTosMtfSignalLabelOptions(saved = {}) {
  if (saved.signalLabelStudyVersion === TOS_MTF_SIGNAL_LABEL_STUDY_VERSION) return {};
  const savedCallColor = String(saved.signal48CallColor || "").toLowerCase();
  const savedCompactCallColor = String(saved.signal920CompactCallColor || "").toLowerCase();
  return {
    signalLabelStudyVersion: TOS_MTF_SIGNAL_LABEL_STUDY_VERSION,
    // Upgrade only known former app defaults. Preserve custom trader colors.
    ...(!savedCallColor || ["#a9ff00", "#fff200", "#ffff00"].includes(savedCallColor)
      ? { signal48CallColor: "#a9ff00" }
      : {}),
    ...(!savedCompactCallColor || ["#00afaf", "#00ffff"].includes(savedCompactCallColor)
      ? { signal920CompactCallColor: "#00afaf" }
      : {}),
    ...(!Object.prototype.hasOwnProperty.call(saved, "signalSessionsBack") || Number(saved.signalSessionsBack) === 5
      ? { signalSessionsBack: 1 }
      : {}),
    signal15m: true,
    signal30m: true,
    signal1h: true,
    signal2h: true,
    signal4h: true,
    signal92030m: true,
    signal9201h: true,
    signal9202h: true,
    signal9204h: true,
    signal920TrendBubbles: true,
    signal92030mBubbles: true,
    signal9201hBubbles: true,
    signal9202hBubbles: true,
    signal9204hBubbles: true,
    signal92030mCompact: true,
    signal9201hCompact: true,
    signal9202hCompact: true,
    signal9204hCompact: true,
  };
}

function chartMtfCloudDefinitions(displayedMinutes, optionPrefix) {
  return [
    { key: "current", label: "Current", minutes: displayedMinutes, optionKey: `${optionPrefix}Current` },
    { key: "15m", label: "15m", minutes: 15, optionKey: `${optionPrefix}15m` },
    { key: "30m", label: "30m", minutes: 30, optionKey: `${optionPrefix}30m` },
    { key: "1h", label: "1h", minutes: 60, optionKey: `${optionPrefix}1h` },
    { key: "2h", label: "2h", minutes: 120, optionKey: `${optionPrefix}2h` },
    { key: "4h", label: "4h", minutes: 240, optionKey: `${optionPrefix}4h` },
  ];
}

// Translation of the supplied one-sided 4×8 cloud study.
// Each crossover paints the full source-timeframe candle: above that candle's
// low for bullish crosses and below its high for bearish crosses.
function calculateMtfOneSidedClouds(bars, currentMinutes, easternSessionFormatter, options = {}) {
  const source = Array.isArray(bars) ? bars : [];
  if (!source.length || !easternSessionFormatter?.formatToParts) return [];
  const displayedMinutes = Math.max(1, Number(currentMinutes) || 1);
  const cutoffTime = chartMtfCloudSessionCutoff(source, easternSessionFormatter, {
    limitRecentSessions: options.mtfCloudLimitRecentSessions,
    sessionsBack: options.mtfCloudSessionsBack,
    rthStartTime: options.mtfCloudRthStartTime,
    rthEndTime: options.mtfCloudRthEndTime,
    defaultSessionsBack: 2,
  });
  const definitions = chartMtfCloudDefinitions(displayedMinutes, "mtfCloud");
  return definitions.flatMap((definition) => {
    // ThinkScript secondary aggregations cannot be lower than the chart's
    // primary aggregation, so hide those combinations here as TOS does.
    if (definition.minutes < displayedMinutes || options[definition.optionKey] === false) return [];
    const timeframeBars = aggregateChartBars(source, definition.minutes);
    const ema4 = calculateChartEma(timeframeBars, 4);
    const ema8 = calculateChartEma(timeframeBars, 8);
    return timeframeBars.flatMap((bar, index) => {
      if (index === 0 || Number(bar.time) < cutoffTime) return [];
      const previousDifference = Number(ema4[index - 1]?.value) - Number(ema8[index - 1]?.value);
      const difference = Number(ema4[index]?.value) - Number(ema8[index]?.value);
      const crossedUp = previousDifference <= 0 && difference > 0;
      const crossedDown = previousDifference >= 0 && difference < 0;
      if (!crossedUp && !crossedDown) return [];
      const anchor = crossedUp ? Number(bar.low) : Number(bar.high);
      if (!Number.isFinite(anchor)) return [];
      return [{
        key: `${definition.key}-${bar.time}-${crossedUp ? "bull" : "bear"}`,
        timeframe: definition.label,
        startTime: Number(bar.time),
        endTime: Number(bar.time) + definition.minutes * 60,
        anchor,
        tone: crossedUp ? "bull" : "bear",
        family: "mtf-4x8",
      }];
    });
  });
}

