    pivotPointsShowOnlyToday: false,
    pivotPointsDisplayNames: true,
    pivotPointsResistanceColor: "#ff0000",
    pivotPointsPivotColor: "#ffffff",
    pivotPointsSupportColor: "#00ff00",
