      if (maximizedChainWidth == null) localStorage.removeItem(MAXIMIZED_CHAIN_WIDTH_STORAGE_KEY);
      else localStorage.setItem(MAXIMIZED_CHAIN_WIDTH_STORAGE_KEY, String(Math.round(maximizedChainWidth)));
