    followLatestTimeScale(timeScale);
    manualPriceNavigationRef.current = false;
    fitVisibleCandlePriceRangeRef.current?.();
    chartInitialViewRef.current = false;
    lastAutoFocusedSymbolRef.current = normalizedChartSymbol;
