function PaperTradeStatusBanner({ dashboard, sessionStatus }) {
  const blockStatus = dashboard.scheduler?.entryBlockStatus || "";
  const blockMessage = dashboard.scheduler?.entryBlockMessage || "";
  const stockAutoReadiness = dashboard.stockAutoReadiness || {};
  const openPositions = Number(dashboard.status?.openPositions || 0);
  const botRunning = dashboard.botState === "Running";
  const accountLabel = dashboard.status?.accountLabel || "Paper";
  const liveSymbols = (dashboard.openPositions || [])
    .map((row) => row.symbol)
    .filter(Boolean)
    .slice(0, 6);

  let title = "Paper bot is idle.";
  let detail = "Start the bot to begin automatic scanning and paper-trade management.";
  let tone = "blue";

  if (botRunning && blockStatus === "daily_cap") {
    title = "Bot is running and managing existing trades.";
    detail = blockMessage || "No new entries right now because the daily trade capital is reached.";
    tone = "gold";
  } else if (botRunning && blockStatus === "buying_power") {
    title = "Bot is running and managing existing trades.";
    detail = blockMessage || "No new entries right now because buying power is too low.";
    tone = "negative";
  } else if (botRunning && blockStatus === "trade_amount") {
    title = "Bot is running, but new entries are blocked.";
    detail = blockMessage || "Per-trade amount is too small for the current setups.";
    tone = "gold";
  } else if (botRunning && openPositions > 0) {
    title = "Bot is running and actively managing paper positions.";
    detail = `${openPositions} open position${openPositions === 1 ? "" : "s"} currently under stop, target, and runner management${liveSymbols.length ? `: ${liveSymbols.join(", ")}` : ""}.`;
    tone = "green";
  } else if (botRunning && sessionStatus?.canAutoTrade) {
    title = "Bot is running and ready for new paper entries.";
    detail = stockAutoReadiness.requiresFreshOi
      ? "Core session: waiting for a fresh A+ HOT or A ACTIVE OI-confirmed stock setup."
      : "Extended session: scanning the complete stock momentum setup; option flow is advisory only.";
    tone = "green";
  } else if (botRunning) {
    title = "Bot is running in monitor mode.";
    detail = sessionStatus?.executionNote || "The bot is waiting for the next tradable stock session.";
  }

  return (
    <section className={`paper-bot-banner tone-${tone}`}>
      <div>
        <span>PAPER TRADE BOT STATUS</span>
        <b>{title}</b>
        <small>{detail}</small>
      </div>
      <div className="paper-bot-banner-meta">
        <strong>{dashboard.botState}</strong>
        <small>{accountLabel}</small>
        <small>{sessionStatus?.currentSession || "Closed"} session</small>
        <small>Position checks: {dashboard.stockPositionManager?.intervalSeconds || 5}s</small>
      </div>
    </section>
  );
}

