    const matchesRating = newsRatingFilter === "all" || Number(row.score || 0) === Number(newsRatingFilter);
    const matchesType = newsTypeFilter === "all" || row.news_type === newsTypeFilter;
    const matchesSentiment = newsSentimentFilter === "all"
