  const optionOpenGreenCount = optionPositionRows.filter((row) => Number(row.pnl ?? row.marked_pnl ?? row.unrealized_pnl ?? 0) > 0).length;
  const optionOpenRedCount = optionPositionRows.filter((row) => Number(row.pnl ?? row.marked_pnl ?? row.unrealized_pnl ?? 0) < 0).length;
  const workflowGreenCount = optionWorkflowActive ? optionOpenGreenCount : openGreenCount;
  const workflowRedCount = optionWorkflowActive ? optionOpenRedCount : openRedCount;
  const optionTakenRows = optionTradeRows
